def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-10):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)

rng = np.random.RandomState(2)
X = np.vstack([rng.randn(12, 2) * 0.4, rng.randn(12, 2) * 0.4 + np.array([3., 0.]),
               rng.randn(12, 2) * 0.4 + np.array([0., 3.])])
n = X.shape[0]
C = np.zeros((n, n))
for i in range(n):
    d = np.empty(n)
    for j in range(n):
        d[j] = ((X[i] - X[j]) ** 2).sum()
    o = np.argsort(d, kind="stable")
    for t in range(1, 4):
        C[i, o[t]] = 1.
for i in range(n):
    for j in range(30, n):
        C[i, j] = 0.
        C[j, i] = 0.
for i in range(30, n - 1):
    C[i, i + 1] = 1.

ch, ncc, nl, par, d = ward_tree(X, connectivity=C)
check("ward_children", [ch])
check("ward_dist", d, 1e-9, 1e-12)
check("ward_ncc", [float(ncc)])
ch, ncc, nl, par, d = linkage_tree(X, connectivity=C, linkage="complete")
check("complete_children", [ch])
check("complete_dist", d, 1e-9, 1e-12)
ch, ncc, nl, par, d = linkage_tree(X, connectivity=C, linkage="average")
check("average_children", [ch])
check("average_dist", d, 1e-9, 1e-12)
ch, ncc, nl, par, d = linkage_tree(X, connectivity=C, linkage="single")
check("single_children", [ch])
check("single_dist", d, 1e-9, 1e-12)
check("agg_ward", AgglomerativeClustering(n_clusters=3, connectivity=C, linkage="ward").fit(X).labels_)
check("agg_complete", AgglomerativeClustering(n_clusters=3, connectivity=C, linkage="complete").fit(X).labels_)
check("agg_average", AgglomerativeClustering(n_clusters=3, connectivity=C, linkage="average").fit(X).labels_)
check("agg_single", AgglomerativeClustering(n_clusters=3, connectivity=C, linkage="single").fit(X).labels_)
check("agg_partial", AgglomerativeClustering(n_clusters=4, connectivity=C, linkage="ward", compute_full_tree=False).fit(X).labels_)
a = AgglomerativeClustering(n_clusters=None, distance_threshold=2.0, connectivity=C, linkage="average").fit(X)
check("agg_thresh", [a.labels_, np.array([float(a.n_clusters_)])])
F = rng.randn(10, 8)
F[:, 4:] += F[:, :4] * 2
fa = FeatureAgglomeration(n_clusters=3).fit(F)
check("fa_labels", fa.labels_)
check("fa_transform", [fa.transform(F)[:3]], 1e-12, 1e-12)
check("fa_inverse", [fa.inverse_transform(fa.transform(F))[:2]], 1e-12, 1e-12)
